import{_ as c,C as r,o as n,c as h,j as d,a as e,E as o,a5 as l}from"./chunks/framework.Dep_XxFZ.js";const g=JSON.parse('{"title":"文本省略","description":"","frontmatter":{},"headers":[],"relativePath":"components/ellipsis.md","filePath":"components/ellipsis.md","lastUpdated":1787173379000}'),s={name:"components/ellipsis.md"},p={id:"文本省略",tabindex:"-1"};function b(u,t,x,f,m,q){const i=r("Badge"),a=r("XhDemo");return n(),h("div",null,[d("h1",p,[t[0]||(t[0]=e("文本省略 ",-1)),o(i,{type:"info",text:"ellipsis"}),t[1]||(t[1]=e()),t[2]||(t[2]=d("a",{class:"header-anchor",href:"#文本省略","aria-label":'Permalink to "文本省略 <Badge type="info" text="ellipsis" />"'},"​",-1))]),t[3]||(t[3]=l('<p>放不下的文本收成省略号，并把&quot;到底有没有被裁掉&quot;如实报出来。</p><h2 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h2><ul><li>表格单元格、列表项、面包屑末段这类宽度不由内容决定的位置。</li><li>需要在真被裁掉时才给出完整文本的提示。</li></ul><h2 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h2><ul><li>文本必须完整可读（价格、编号、错误原因）：换布局，别裁。</li><li>要裁的是一整块正文并需要&quot;展开全文&quot;的阅读体验：可以用本组件的 <code>expandable</code>，但更长的正文交给<a href="./typography">排印</a>加自己的折叠。</li></ul><h2 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h2><ul><li><code>lines</code> 为 1 走单行省略，大于 1 按行数裁、末行收省略号。</li><li>溢出结论会实测并在翻面时回调，不靠猜。</li><li><code>expandable</code> 让整块文字变成一颗按钮，Enter / Space 也按得动。</li><li><code>tooltip</code> 在真被裁掉时把整段文字交给平台的原生提示。</li></ul><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="基础用法" tabindex="-1">基础用法 <a class="header-anchor" href="#基础用法" aria-label="Permalink to &quot;基础用法&quot;">​</a></h3><p>一行放不下就收成省略号；有没有被裁如实报出来</p>',10)),o(a,{src:"ellipsis/01-basic"}),t[4]||(t[4]=d("h3",{id:"行数",tabindex:"-1"},[e("行数 "),d("a",{class:"header-anchor",href:"#行数","aria-label":'Permalink to "行数"'},"​")],-1)),t[5]||(t[5]=d("p",null,"lines 为 1 走单行省略，大于 1 按行数裁，末行收省略号",-1)),o(a,{src:"ellipsis/02-lines"}),t[6]||(t[6]=d("h3",{id:"点击展开",tabindex:"-1"},[e("点击展开 "),d("a",{class:"header-anchor",href:"#点击展开","aria-label":'Permalink to "点击展开"'},"​")],-1)),t[7]||(t[7]=d("p",null,"expandable 让整块文字变成一颗按钮，Enter / Space 也按得动",-1)),o(a,{src:"ellipsis/03-expandable"}),t[8]||(t[8]=d("h3",{id:"溢出才提示",tabindex:"-1"},[e("溢出才提示 "),d("a",{class:"header-anchor",href:"#溢出才提示","aria-label":'Permalink to "溢出才提示"'},"​")],-1)),t[9]||(t[9]=d("p",null,"上面套 Tooltip 按 overflow-change 开关，下面用 tooltip 交给平台的原生提示",-1)),o(a,{src:"ellipsis/04-overflow-tooltip"}),t[10]||(t[10]=l('<h2 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-ellipsis&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhEllipsis</code></td></tr><tr><td>组合式函数</td><td><code>useEllipsis</code></td></tr><tr><td>状态机</td><td><code>ellipsisMachine</code></td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/ellipsis.css</code></td></tr></tbody></table><h2 id="解剖" tabindex="-1">解剖 <a class="header-anchor" href="#解剖" aria-label="Permalink to &quot;解剖&quot;">​</a></h2><p>部件名即 <code>data-part</code> 属性值，也是皮肤的选择器。加粗的是必备部件，不渲染它组件不工作（Web Components 适配器会在诊断通道上报 <code>wc.missing-part</code>）。</p><p><code>data-scope=&quot;ellipsis&quot;</code>：<strong><code>root</code></strong></p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>lines</code></td><td><code>number</code></td><td></td><td>夹几行，1 为单行，默认 1。</td></tr><tr><td><code>expandable</code></td><td><code>boolean</code></td><td></td><td>点一下铺开全文。</td></tr><tr><td><code>expanded</code></td><td><code>boolean</code></td><td></td><td>受控展开；缺省即非受控。</td></tr><tr><td><code>defaultExpanded</code></td><td><code>boolean</code></td><td></td><td>非受控时的初始展开态。</td></tr><tr><td><code>tooltip</code></td><td><code>boolean</code></td><td></td><td>真被裁掉了才把整段文字交给平台的原生提示。</td></tr><tr><td><code>onExpandedChange</code></td><td><code>(details: EllipsisExpandedChangeDetails) =&gt; void</code></td><td></td><td>expanded 变化意图回调；受控时是唯一出口，非受控随内部转移一并通知。</td></tr><tr><td><code>onOverflowChange</code></td><td><code>(details: EllipsisOverflowChangeDetails) =&gt; void</code></td><td></td><td>量出来的溢出结论翻面时回调。</td></tr></tbody></table><h2 id="事件" tabindex="-1">事件 <a class="header-anchor" href="#事件" aria-label="Permalink to &quot;事件&quot;">​</a></h2><p>自定义元素派发这些事件，Vue 组件对应同名 emit；载荷都在 <code>detail</code> 上。可双向绑定的值另有 <code>update:xxx</code>，见 Props。</p><table tabindex="0"><thead><tr><th>事件</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>expanded-change</code></td><td><code>EllipsisExpandedChangeDetails</code></td><td>展开状态变化；detail 为 <code>{ expanded: boolean }</code></td></tr><tr><td><code>overflow-change</code></td><td><code>EllipsisOverflowChangeDetails</code></td><td>溢出结论翻面；detail 为 <code>{ overflowing: boolean }</code></td></tr></tbody></table><h2 id="插槽" tabindex="-1">插槽 <a class="header-anchor" href="#插槽" aria-label="Permalink to &quot;插槽&quot;">​</a></h2><p>作者能拿到载荷的插槽。只转发内容、不带载荷的默认插槽不在此列——那类直接写子节点即可。</p><table tabindex="0"><thead><tr><th>Vue 组件</th><th>插槽</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>XhEllipsis</code></td><td><code>default</code></td><td><code>EllipsisSlotProps</code></td><td></td></tr></tbody></table><h2 id="状态" tabindex="-1">状态 <a class="header-anchor" href="#状态" aria-label="Permalink to &quot;状态&quot;">​</a></h2><p>对外可见的状态落在 <code>data-state</code> 上，写样式与断言都读它：</p><table tabindex="0"><thead><tr><th>部件</th><th>取值</th></tr></thead><tbody><tr><td><code>root</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr></tbody></table><p>状态机内部转移，写样式与业务都用不到；要监听变化请看上面的「事件」。</p><p><strong>状态</strong>：<code>collapsed</code> · <code>expanded</code></p><p><strong>事件</strong>：<code>MEASURE</code> · <code>TOGGLE</code> · <code>CONTROLLED.EXPAND</code> · <code>CONTROLLED.COLLAPSE</code></p><p><strong>判据</strong>：<code>isExpandedControlled</code></p><h2 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h2><p><code>useEllipsis</code> 产出的对象。<code>getXxxProps()</code> 铺到对应部件的宿主元素上，其余是可读状态与操作入口。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>expanded</code></td><td><code>boolean</code></td><td>此刻是不是铺开了全文。</td></tr><tr><td><code>overflowing</code></td><td><code>boolean</code></td><td>夹住的那一版有没有被裁掉内容。作者据此决定要不要套一层提示。</td></tr><tr><td><code>setExpanded</code></td><td><code>(next: boolean) =&gt; void</code></td><td>程序化展开 / 收回，与点一下走同一条路。</td></tr><tr><td><code>measure</code></td><td><code>() =&gt; void</code></td><td>手动重量一次：字体到位、外层换了布局这类观察器看不见的变化，由作者补一枪。</td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr></tbody></table><h2 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h2><p>规格出处：<a href="https://www.w3.org/WAI/ARIA/apg/patterns/button/" target="_blank" rel="noreferrer">W3C APG</a></p><table tabindex="0"><thead><tr><th>按键</th><th>生效条件</th><th>行为</th></tr></thead><tbody><tr><td><code>Enter</code> / <code>Space</code></td><td>expandable，焦点在 root 上</td><td>铺开全文 / 收回夹住的那一版；Space 拦掉翻页的默认动作</td></tr><tr><td><code>Tab</code> / <code>Shift+Tab</code></td><td>expandable</td><td>停到这块文字上；不可展开时它不带 tabindex，不在 Tab 序列里</td></tr></tbody></table><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><p>下面这些由 <code>connect</code> 铺到部件上，作者不必自己写；重复写反而会覆盖掉正确值。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>aria-expanded</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>root</code></td><td><code>role</code></td><td>&#39;button&#39;</td></tr></tbody></table><h2 id="样式" tabindex="-1">样式 <a class="header-anchor" href="#样式" aria-label="Permalink to &quot;样式&quot;">​</a></h2><p>默认皮肤 <code>@xihan-ui/styles/ellipsis.css</code> 按部件选择：<code>[data-scope=&quot;ellipsis&quot;][data-part=&quot;root&quot;]</code>。它落在 <code>xihan.components</code> 层；业务样式不写进 <code>@layer</code> 即高于全部库层，要按层压过来就写进 <code>xihan.overrides</code>。</p><h2 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h2><p>由 <code>connect</code> 产出并铺到部件上，皮肤与测试都据此选择；<code>data-disabled</code> 这类无值属性在条件不成立时整个不出现。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-expandable</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-lines</code></td><td>String(lines)</td></tr><tr><td><code>root</code></td><td><code>data-multiline</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-overflowing</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-state</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr></tbody></table><h2 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h2><ul><li>外面套<a href="./tooltip">文字提示</a>，按溢出回调开关，可以拿到与站点一致的提示样式。</li></ul><h2 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h2><ul><li>只在裁掉时才给提示：没裁还弹提示是纯噪音。</li><li>展开态要能收回去，否则布局在一次点击后再也回不来。</li></ul><h2 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h2><ul><li>用固定字符数截断字符串代替本组件：等宽假设在中英混排与不同字体下都不成立。</li><li>裁掉之后不提供任何看到全文的途径。</li></ul>',40))])}const E=c(s,[["render",b]]);export{g as __pageData,E as default};
